<script>
(function(){
    document.querySelectorAll('img').forEach(function(img){
        img.addEventListener('error', function(){
            if (img.dataset.wcFallbackApplied) return;
            img.dataset.wcFallbackApplied = '1';
            const box = document.createElement('div');
            box.className = 'wc-broken-image';
            box.style.width = img.clientWidth ? img.clientWidth + 'px' : '100%';
            box.style.height = img.clientHeight ? img.clientHeight + 'px' : '160px';
            img.replaceWith(box);
        });
    });
})();
</script>

